# Onett - Mother4  (32x24, built from OnettTileset_Reference.md)
# All multi-tile stamps use verified-adjacent tiles (Appendix B). Do NOT hand-pick
# every-other index for a building - neighbouring tiles only seam one specific way.
[legend]
# ---- ground / vegetation (varied so it isn't one flat green) ----
. = 4        # grass
, = 16       # grass (variant)
: = 9        # grass w/ tuft
; = 25       # grass w/ tuft (variant)
* = 37       # flower scatter (overlay - drops on any grass)
o = 30       # flowerbed left   \ verified pair 30-31
p = 31       # flowerbed right  /

# ---- water ----
w = 663      # ocean / pond fill

# ---- road (pavement) ----
r = 289      # pavement

# ---- street props (single overlay tiles) ----
m = 310      # mailbox
s = 312      # stop sign
x = 316      # manhole left   \
y = 317      # manhole mid     > verified run 316-317-318
z = 318      # manhole right  /
O = 362      # ONETT sign left  \ verified pair 362-363
N = 363      # ONETT sign right /

# ---- trees ----
T = 183      # canopy         \
t = 184      # canopy          > verified run 183-184-185
u = 185      # canopy         /
V = 192      # tree top       \
Y = 208      # tree trunk      > verified 3-tall tree 192-208-224
Z = 224      # tree base      /

# ---- gray civic house: verified 6-wide roof (386-391) over 6-wide wall (402-407) ----
a = 386      # roof [
b = 387      # roof
c = 388      # roof
d = 389      # roof
e = 390      # roof
f = 391      # roof ]
g = 402      # wall [
h = 403      # wall
i = 404      # wall
j = 405      # wall
k = 406      # wall
l = 407      # wall ]

